"use strict";(()=>{const root=document.getElementById('worldQuizRoot'),title=document.getElementById('worldQuizTitle'),params=new URLSearchParams(location.search),topic=params.get('topic')||'planets';if(!root)return;const speak=text=>{if(!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-IN';u.rate=.76;speechSynthesis.speak(u)},shuffle=a=>[...a].sort(()=>Math.random()-.5);const planetQuestions=[['Which planet is closest to the Sun?',['Mercury','Venus','Earth','Mars','Jupiter'],'Mercury'],['Which planet is our home?',['Earth','Mars','Venus','Saturn','Neptune'],'Earth'],['Which is the largest planet?',['Jupiter','Earth','Mars','Mercury','Venus'],'Jupiter'],['Which planet is famous for its rings?',['Saturn','Mars','Earth','Mercury','Neptune'],'Saturn'],['Which planet is called the Red Planet?',['Mars','Venus','Uranus','Earth','Jupiter'],'Mars'],['Which is the 8th planet from the Sun?',['Neptune','Uranus','Saturn','Earth','Mars'],'Neptune'],['Which is the 7th planet from the Sun?',['Uranus','Neptune','Jupiter','Venus','Mercury'],'Uranus'],['Which planet is 2nd from the Sun?',['Venus','Earth','Mercury','Mars','Saturn'],'Venus'],['Which planet is 6th from the Sun?',['Saturn','Jupiter','Uranus','Mars','Earth'],'Saturn'],['How many major planets orbit our Sun?',['8','7','9','10','6'],'8']];const countries=window.LEARNWITHUS_COUNTRIES||[];let questions,label,lesson;if(topic==='countries'){label='Countries & Capitals';lesson='countries-capitals.html';questions=shuffle(countries).slice(0,10).map(item=>{const wrong=shuffle(countries.filter(x=>x.capital!==item.capital).map(x=>x.capital)).slice(0,4);return['What is the capital of '+item.country+'?',shuffle([item.capital,...wrong]),item.capital]})}else{label='Planets';lesson='planets.html';questions=planetQuestions}title.textContent=label+' Quiz';let index=0,score=0;function finish(){const needsReview=score<8;root.innerHTML='<section class="practice-box"><p class="game-progress">Quiz complete</p><p class="game-question">'+score+' / 10</p><p class="game-feedback">'+(needsReview?'Good try. Review the learning page and try once more.':'Excellent work! You are ready for another challenge.')+'</p><div id="sharedScoreCard"></div><div class="journey-actions"><button id="worldAgain" class="practice-button journey-primary">Play again</button><a class="practice-button journey-secondary" href="'+lesson+'">'+(needsReview?'📖 Review the lesson':'Review learning')+'</a></div></section>';window.renderLearnWithUsScoreCard?.({container:document.getElementById('sharedScoreCard'),score,total:10,title:label+' Quiz',subtitle:needsReview?'Review, remember and try again.':'Fantastic world-learning result!',filename:'learnwithus-'+topic+'-score.svg',url:'world-quiz.html?topic='+topic});window.LearnWithUs?.recordQuiz?.(label+' quiz',score,10,'world-quiz.html?topic='+topic);document.getElementById('worldAgain').onclick=()=>location.reload()}function round(){if(index>=10)return finish();const q=questions[index];root.innerHTML='<section class="practice-box"><p class="game-progress">Question '+(index+1)+' of 10</p><p class="game-question">'+q[0]+'</p><div class="game-options" id="worldOptions"></div><p class="game-feedback" id="worldFeedback" role="status" aria-live="polite"></p><button class="practice-button game-next" id="worldNext" hidden>'+(index===9?'See score →':'Next →')+'</button></section>';const row=document.getElementById('worldOptions'),fb=document.getElementById('worldFeedback'),next=document.getElementById('worldNext');q[1].forEach(v=>{const b=document.createElement('button');b.type='button';b.textContent=v;b.onclick=()=>{const ok=v===q[2];row.querySelectorAll('button').forEach(x=>{x.disabled=true;if(x.textContent===q[2])x.classList.add('correct')});b.classList.add(ok?'correct':'wrong');const msg=ok?'Correct answer!':'Wrong answer. The correct answer is '+q[2]+'.';fb.textContent=msg;speak(msg);if(ok)score++;next.hidden=false;next.focus()};row.append(b)});next.onclick=()=>{index++;round()}}round()})();